"use client";
import useSWR from "swr";

const fetcher = (url: string) => fetch(url).then((res) => res.json());

export default function Rnlist({ initialdata }: { initialdata: any }) {
  const { data, error } = useSWR("http://localhost:3001/get-user", fetcher, {
    fallbackData: initialdata,
    refreshInterval: 5000,
  });

  
  const users = data?.data || (Array.isArray(data) ? data : []);
  if (error) {
    return (
      <div>
        <p> dailed show the user lsit </p>
      </div>
    );
  }
  return (
    <div className="flex flex-col gap-2 p-4 border border-dashed border-orange-200 rounded-xl bg-orange-50/30">
      <h2 className="text-xs font-bold text-orange-600 uppercase tracking-widest mb-2">
        Live User Stream
      </h2>

      {users.map((ele: any) => (
        <div key={ele._id?.toString()} className="flex items-center gap-3 py-1">
          <div className="h-2 w-2 rounded-full bg-green-500 animate-pulse" />
          <span className="font-medium text-slate-700">{ele.name}</span>
          <span className="text-xs text-slate-400">ID: {ele.userId}</span>
        </div>
      ))}
    </div>
  );
}
